    public static function svg(string $nombre, string $clase = '', ?string $etiqueta = null, int|string|null $tam = 18): string
    {
        $medidas = $tam ? 'width="' . e($tam) . '" height="' . e($tam) . '" ' : '';
        $trazos = self::PATHS[$nombre] ?? self::PATHS['utensils'];
        $accesible = $etiqueta !== null
            ? 'role="img" aria-label="' . e($etiqueta) . '"'
            : 'aria-hidden="true" focusable="false"';

        return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" ' . $medidas . 'class="l501-icon ' . e($clase) . '" ' . $accesible . '>' . $trazos . '</svg>';
    }
